import Checkbox from "@marko-ui/shadcn/ui/checkbox/checkbox.marko";
import Field from "@marko-ui/shadcn/ui/field/field.marko";
import FieldContent from "@marko-ui/shadcn/ui/field/field-content.marko";
import FieldDescription from "@marko-ui/shadcn/ui/field/field-description.marko";
import FieldLabel from "@marko-ui/shadcn/ui/field/field-label.marko";

<Field class="mx-auto w-72" orientation="horizontal">
  <Checkbox id="checkbox-description-terms" ids={ hiddenInput: "checkbox-description-terms" } defaultChecked/>
  <FieldContent>
    <FieldLabel for="checkbox-description-terms">Accept terms and conditions</FieldLabel>
    <FieldDescription>By clicking this checkbox, you agree to the terms and conditions.</FieldDescription>
  </FieldContent>
</Field>

import Checkbox from "@marko-ui/shadcn/ui/checkbox/checkbox.marko";
import Table from "@marko-ui/shadcn/ui/table/table.marko";
import TableHeader from "@marko-ui/shadcn/ui/table/header.marko";
import TableBody from "@marko-ui/shadcn/ui/table/body.marko";
import TableRow from "@marko-ui/shadcn/ui/table/row.marko";
import TableHead from "@marko-ui/shadcn/ui/table/head.marko";
import TableCell from "@marko-ui/shadcn/ui/table/cell.marko";

static const tableData = [
  { id: "1", name: "Sarah Chen", email: "sarah.chen@example.com", role: "Admin" },
  { id: "2", name: "Marcus Rodriguez", email: "marcus.rodriguez@example.com", role: "User" },
  { id: "3", name: "Priya Patel", email: "priya.patel@example.com", role: "User" },
  { id: "4", name: "David Kim", email: "david.kim@example.com", role: "Editor" },
];

<let/selectedRows=(new Set(["1"]) as Set<string>)/>
<const/selectAll=(selectedRows.size === tableData.length)/>

<const/handleSelectAll=(checked: boolean | "indeterminate") => {
  selectedRows = checked === true ? new Set(tableData.map((row) => row.id)) : new Set();
}/>

<const/handleSelectRow=(id: string, checked: boolean | "indeterminate") => {
  const next = new Set(selectedRows);
  if (checked === true) {
    next.add(id);
  } else {
    next.delete(id);
  }
  selectedRows = next;
}/>

<Table>
  <TableHeader>
    <TableRow>
      <TableHead class="w-8">
        <Checkbox
          id="checkbox-table-select-all"
          aria-label="Select all"
          checked=selectAll
          checkedChange=handleSelectAll
        />
      </TableHead>
      <TableHead>Name</TableHead>
      <TableHead>Email</TableHead>
      <TableHead>Role</TableHead>
    </TableRow>
  </TableHeader>
  <TableBody>
    <for|row| of=tableData>
      <TableRow data-state=(selectedRows.has(row.id) ? "selected" : undefined)>
        <TableCell>
          <Checkbox
            id=`checkbox-table-row-${row.id}`
            aria-label=`Select ${row.name}`
            checked=selectedRows.has(row.id)
            checkedChange=(checked) => handleSelectRow(row.id, checked)
          />
        </TableCell>
        <TableCell class="font-medium">${row.name}</TableCell>
        <TableCell>${row.email}</TableCell>
        <TableCell>${row.role}</TableCell>
      </TableRow>
    </for>
  </TableBody>
</Table>
